xql_query:
// ============================================================
// Rule: GIT_Repository Created
// Vendor: GIT
// Objective:
// Detect activity associated with GIT_Repository Created.
// Severity: SEV_020_LOW
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0010 - Exfiltration
// Technique: T1567 - Exfiltration Over Web Service
// Technique: T1567.001 - Exfiltration Over Web Service: Exfiltration to Code Repository

// Fonte de dados: logs brutos do GitHub
dataset = github_github_raw  

// Filtra apenas eventos onde a ação registrada seja "created"
// (indica criação de um novo repositório)
| filter action = "created"  

// Criação de campos derivados para facilitar a leitura dos resultados
| alter
    user = sender -> login,                   // Usuário que realizou a criação
    enterprise_name = enterprise -> name,     // Nome da organização/enterprise no GitHub
    git_url = repository -> git_url,          // URL do repositório criado
    private = repository -> private,          // Se o repositório é privado ou público
    description = repository -> description   // Descrição fornecida no repositório

// Seleção dos campos principais para exibição
| fields user, enterprise_name, git_url, private, description
